-- AD33 CHECK (B13 T3c apply a verified verdict to a case): every row must be true
SELECT 'the ledger kind sender.applied is on the closed list (info)' AS rule, EXISTS (SELECT 1 FROM desk.fadm_ledger_kind WHERE kind = 'sender.applied' AND severity = 'info') AS ok
UNION ALL SELECT 'fadm_case_apply_resolution is SECURITY DEFINER with fixed search_path, 5 s statement and 2 s lock timeout, commented; desk_app may run it, PUBLIC may not',
  EXISTS (SELECT 1 FROM pg_proc p WHERE p.pronamespace = 'desk'::regnamespace AND p.proname = 'fadm_case_apply_resolution' AND p.prosecdef AND p.proconfig::text LIKE '%search_path=pg_catalog, desk%' AND p.proconfig::text LIKE '%statement_timeout=5s%' AND p.proconfig::text LIKE '%lock_timeout=2s%' AND obj_description(p.oid, 'pg_proc') IS NOT NULL)
  AND has_function_privilege('desk_app', 'desk.fadm_case_apply_resolution(text)', 'EXECUTE') AND NOT has_function_privilege('public', 'desk.fadm_case_apply_resolution(text)', 'EXECUTE')
UNION ALL SELECT 'the door takes only a case ref (no address or domain parameter)', (SELECT pg_get_function_arguments(p.oid) FROM pg_proc p WHERE p.pronamespace = 'desk'::regnamespace AND p.proname = 'fadm_case_apply_resolution') = 'p_case text'
UNION ALL SELECT 'every binding made from a verified answer keeps its request id as evidence (FACT over all rows so far)', NOT EXISTS (SELECT 1 FROM desk.fadm_case_binding WHERE source = 'verified_domain' AND NOT (evidence ? 'request'))
UNION ALL SELECT 'no sender.applied line holds an address or a key outside the closed set (FACT)', NOT EXISTS (SELECT 1 FROM desk.fadm_ledger l, jsonb_object_keys(l.detail) k WHERE l.kind = 'sender.applied' AND k NOT IN ('case', 'word', 'request')) AND NOT EXISTS (SELECT 1 FROM desk.fadm_ledger WHERE kind = 'sender.applied' AND detail::text ~ '@')
UNION ALL SELECT 'the ledger chain verifies', desk.fadm_ledger_verify()
UNION ALL SELECT 'earlier phases are untouched (AD30 writer and AD32 log still closed to PUBLIC)', NOT has_function_privilege('public', 'desk.fadm_case_bind(text,uuid,text,uuid,uuid,jsonb)', 'EXECUTE') AND NOT has_function_privilege('public', 'desk.fadm_resolve_log(text,uuid,text,text,uuid)', 'EXECUTE');
